$$
\begin{aligned}\frac{1}{2}{\int }_{-1}^{1}\frac{1}{{sinh}^{2}⁡x}\cdot {tanh}^{2}⁡x\,\text{d}x & =\frac{1}{2}{\int }_{-1}^{1}\frac{1}{{sinh}^{2}⁡x}\cdot \frac{{sinh}^{2}⁡x}{{cosh}^{2}⁡x}\,\text{d}x \\  & =\frac{1}{2}{\int }_{-1}^{1}\frac{{sinh}^{2}⁡x}{{sinh}^{2}⁡x}\cdot \frac{1}{{cosh}^{2}⁡x}\,\text{d}x \\  & =\frac{1}{2}{\int }_{-1}^{1}\frac{1}{{cosh}^{2}⁡x}\,\text{d}x \\  & =\frac{1}{2}{\int }_{-1}^{1}{sech}^{2}⁡x \\  & =\frac{1}{2}\operatorname{tanh}⁡x{|}_{-1}^{1} \\  & =\frac{1}{2}(\operatorname{tanh}⁡(1)-\operatorname{tanh}⁡(-1)) \\  & =\frac{1}{2}(\frac{e-{e}^{-1}}{e+{e}^{-1}}-\frac{{e}^{-1}-e}{{e}^{-1}+e}) \\  & =\frac{1}{2}(\frac{{e}^{2}-1}{{e}^{2}+1}-\frac{1-{e}^{2}}{1+{e}^{2}}) \\  & =\frac{1}{2}(2\cdot \frac{{e}^{2}-1}{{e}^{2}+1}) \\  & =\frac{{e}^{2}-1}{{e}^{2}+1}\end{aligned}
$$

